import { IngestPipeline } from "@514labs/moose-lib";

// Event data model matching the CSV structure
export interface Event {
  event_id: string;
  event_ts: Date;
  user_id: string;
  event_type: string;
  value: number;
}

// Create ingestion pipeline for events
export const EventPipeline = new IngestPipeline<Event>("Event", {
  table: {
    orderByFields: ["user_id", "event_ts"]
  },
  stream: true,
  ingestApi: true,
});

