const fs = require('fs');
const path = require('path');

// Function to parse different date formats
function parseDateTime(dateStr) {
    // Handle ISO 8601 format (2026-01-15T10:00:00Z)
    if (dateStr.includes('T') && dateStr.includes('Z')) {
        return new Date(dateStr).toISOString();
    }

    // Handle DD/MM/YYYY format
    if (dateStr.includes('/')) {
        const [day, month, year] = dateStr.split('/');
        // Convert to ISO format with a default time
        return new Date(year, month - 1, day, 12, 0, 0).toISOString();
    }

    // Fallback
    return new Date(dateStr).toISOString();
}

// Function to normalize value field (convert nulls to 0)
function normalizeValue(value) {
    if (!value || value.toLowerCase() === 'null' || value.toLowerCase() === 'n/a' || value.trim() === '') {
        return 0;
    }
    return parseFloat(value);
}

// Function to clean a CSV line (remove trailing commas)
function cleanCSVLine(line) {
    return line.replace(/,+$/, '');
}

// Function to process a single CSV file
async function processCSVFile(filePath) {
    console.log(`Processing file: ${filePath}`);

    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.trim().split('\n');

    const events = [];
    let headerSeen = false;

    for (let i = 0; i < lines.length; i++) {
        const cleanLine = cleanCSVLine(lines[i].trim());
        if (!cleanLine) continue;

        const fields = cleanLine.split(',');

        // Skip header rows (first occurrence and any duplicates)
        if (fields[0] === 'event_id') {
            if (!headerSeen) {
                headerSeen = true;
                console.log(`  Header found at line ${i + 1}`);
            } else {
                console.log(`  Duplicate header found at line ${i + 1}, skipping`);
            }
            continue;
        }

        if (fields.length >= 5) {
            const event = {
                event_id: fields[0],
                event_ts: parseDateTime(fields[1]),
                user_id: fields[2],
                event_type: fields[3],
                value: normalizeValue(fields[4])
            };

            events.push(event);
            console.log(`  Processed event: ${event.event_id}`);
        }
    }

    return events;
}

// Function to send events to Moose ingestion API
async function sendEventsToMoose(events) {
    const endpoint = 'http://localhost:4000/ingestion/Event';

    console.log(`Sending ${events.length} events to ${endpoint}`);

    for (const event of events) {
        try {
            const response = await fetch(endpoint, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(event)
            });

            if (response.ok) {
                console.log(`  ✓ Sent event ${event.event_id}`);
            } else {
                console.error(`  ✗ Failed to send event ${event.event_id}: ${response.status} ${response.statusText}`);
                const errorText = await response.text();
                console.error(`    Error details: ${errorText}`);
            }
        } catch (error) {
            console.error(`  ✗ Network error sending event ${event.event_id}:`, error.message);
        }
    }
}

// Main function
async function main() {
    const csvDir = '/data/csv';
    const csvFiles = fs.readdirSync(csvDir).filter(file => file.endsWith('.csv'));

    console.log(`Found ${csvFiles.length} CSV files to process`);

    let allEvents = [];

    // Process each CSV file
    for (const file of csvFiles) {
        const filePath = path.join(csvDir, file);
        const events = await processCSVFile(filePath);
        allEvents = allEvents.concat(events);
    }

    console.log(`\nTotal events processed: ${allEvents.length}`);

    // Send all events to Moose
    await sendEventsToMoose(allEvents);

    console.log('\nData loading completed!');
}

// Run the script
main().catch(console.error);

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// Function to parse different date formats
function parseDateTime(dateStr) {
    // Handle ISO 8601 format (2026-01-15T10:00:00Z)
    if (dateStr.includes('T') && dateStr.includes('Z')) {
        return new Date(dateStr).toISOString();
    }

    // Handle DD/MM/YYYY format
    if (dateStr.includes('/')) {
        const [day, month, year] = dateStr.split('/');
        // Convert to ISO format with a default time
        return new Date(year, month - 1, day, 12, 0, 0).toISOString();
    }

    // Fallback
    return new Date(dateStr).toISOString();
}

// Function to normalize value field (convert nulls to 0)
function normalizeValue(value) {
    if (!value || value.toLowerCase() === 'null' || value.toLowerCase() === 'n/a' || value.trim() === '') {
        return 0;
    }
    return parseFloat(value);
}

// Function to clean a CSV line (remove trailing commas)
function cleanCSVLine(line) {
    return line.replace(/,+$/, '');
}

// Function to process a single CSV file
function processCSVFile(filePath) {
    console.log(`Processing file: ${filePath}`);

    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.trim().split('\n').filter(line => line.trim()); // Remove empty lines

    const events = [];
    let headerSeen = false;

    for (let i = 0; i < lines.length; i++) {
        const cleanLine = cleanCSVLine(lines[i].trim());
        if (!cleanLine) continue;

        const fields = cleanLine.split(',').map(f => f.trim());

        // Skip header rows (first occurrence and any duplicates)
        if (fields[0] === 'event_id') {
            if (!headerSeen) {
                headerSeen = true;
                console.log(`  Header found at line ${i + 1}`);
            } else {
                console.log(`  Duplicate header found at line ${i + 1}, skipping`);
            }
            continue;
        }

        // Ensure we have at least 5 fields (pad with empty string if necessary)
        while (fields.length < 5) {
            fields.push('');
        }

        const event = {
            event_id: fields[0],
            event_ts: parseDateTime(fields[1]),
            user_id: fields[2],
            event_type: fields[3],
            value: normalizeValue(fields[4])
        };

        events.push(event);
        console.log(`  Processed event: ${event.event_id} (value: ${event.value})`);
    }

    return events;
}

// Function to send an event using curl
function sendEventWithCurl(event) {
    const endpoint = 'http://localhost:4000/ingestion/Event';
    const jsonData = JSON.stringify(event);

    try {
        const result = execSync(`curl -s -X POST -H "Content-Type: application/json" -d '${jsonData}' ${endpoint}`, {
            encoding: 'utf8',
            timeout: 10000
        });

        console.log(`  ✓ Sent event ${event.event_id}`);
        return true;
    } catch (error) {
        console.error(`  ✗ Failed to send event ${event.event_id}: ${error.message}`);
        return false;
    }
}

// Main function
function main() {
    const csvDir = '/data/csv';
    const csvFiles = fs.readdirSync(csvDir).filter(file => file.endsWith('.csv')).sort();

    console.log(`Found ${csvFiles.length} CSV files to process`);

    let allEvents = [];

    // Process each CSV file
    for (const file of csvFiles) {
        const filePath = path.join(csvDir, file);
        const events = processCSVFile(filePath);
        allEvents = allEvents.concat(events);
        console.log(`  File ${file}: ${events.length} events\n`);
    }

    console.log(`Total events processed: ${allEvents.length}`);
    console.log('\nSending events to Moose...\n');

    // Send all events to Moose
    let successCount = 0;
    for (const event of allEvents) {
        if (sendEventWithCurl(event)) {
            successCount++;
        }
    }

    console.log(`\nData loading completed! ${successCount}/${allEvents.length} events sent successfully.`);
}

// Run the script
main();

